'use strict';
const bcrypt = require('bcryptjs'); const db = require('../src/db');
async function main() { if (process.env.ALLOW_BOOTSTRAP_ADMIN !== '1' && process.env.NODE_ENV !== 'test') throw new Error('Set ALLOW_BOOTSTRAP_ADMIN=1 for this explicit operation'); const tenant=process.env.BOOTSTRAP_TENANT_ID||process.env.TENANT_ID||process.env.BOOTSTRAP_TENANT_SLUG; const email=String(process.env.BOOTSTRAP_EMAIL||process.env.ADMIN_EMAIL||'').toLowerCase(); const password=process.env.BOOTSTRAP_PASSWORD||process.env.ADMIN_PASSWORD; if (!tenant || !email || typeof password !== 'string' || password.length < 12) throw new Error('Tenant, email, and password of at least 12 characters are required'); const found=await db.query('SELECT id FROM users WHERE tenant_id=$1', [tenant]); if (found.rows.length) throw new Error('Tenant already has users; bootstrap will not overwrite'); const hash=await bcrypt.hash(password, 12); await db.query('INSERT INTO users(email,password_hash,name,role,company,tenant_id) VALUES($1,$2,$3,$4,$5,$6)', [email,hash,process.env.BOOTSTRAP_NAME||process.env.ADMIN_NAME||'Bootstrap Admin','admin',process.env.BOOTSTRAP_COMPANY||null,tenant]); await db.pool.end(); }
main().catch((error)=>{ console.error(error.message); process.exitCode=1; });
